    for dep in deps:
        add_required_domains(dep)

def get_imports(self):
    refs = set()
    for type_ in self.types:
        refs |= type_.get_refs()
    for command in self.commands:
        refs |= command.get_refs()
    for event in self.events:
        refs |= event.get_refs()
    dependencies = set()
    for ref in refs:
        try:
            domain, _ = ref.split(".")
        except ValueError:
            continue
        if domain != self.domain:
            dependencies.add(snake_case(domain))

    return dependencies

